package com.zomiggy.controller; import com.zomiggy.dto.ApiDtos.*; import com.zomiggy.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService service; public AuthController(AuthService s){service=s;} @PostMapping("/request-otp") public ResponseEntity<?> request(@Valid @RequestBody OtpRequest r){var code=service.request(r);var body=new java.util.HashMap<String,Object>();body.put("message","OTP sent successfully");body.put("expiresIn",30);if(code!=null)body.put("otp",code);return ResponseEntity.ok(body);} @PostMapping("/verify-otp") public AuthResponse verify(@Valid @RequestBody VerifyOtpRequest r){return service.verify(r);} @PostMapping("/logout") public Map<String,String> logout(){return Map.of("message","Logged out");}}